231	  const { field, reserved } = destination;
232	  if (raw === undefined || raw === null) return { names: [], problems: [] };
233	
234	  if (!Array.isArray(raw)) {
235	    return { names: [], problems: [`\`${field}\` must be an array of secret names.`] };
236	  }
