238	  const problems: string[] = [];
239	  const names: string[] = [];
240	  const seen = new Set<string>();
241	
242	  for (const entry of raw) {
243	    if (typeof entry !== "string") {
244	      problems.push(`\`${field}\` entries must be strings; found ${JSON.stringify(entry)}.`);
245	      continue;
246	    }
247	    const name = entry.trim();
248	    if (!NAME_PATTERN.test(name)) {
249	      problems.push(
250	        `\`${field}\`: '${name}' is not a usable secret name. Expected uppercase letters, digits and underscores, starting with a letter — e.g. 'SLACK_TOKEN'.`,
251	      );
252	      continue;
253	    }
254	    if (reserved.has(name)) {
255	      problems.push(
256	        `\`${field}\`: '${name}' is already part of the environment this workflow provides, so declaring it would replace that value rather than add a credential. Give the secret another name.`,
257	      );
258	      continue;
259	    }
260	    if (name.startsWith(SECRET_SLOT_PREFIX)) {
261	      problems.push(
262	        `\`${field}\`: '${name}' collides with the slots this mechanism uses internally. Give the secret another name.`,
263	      );
264	      continue;
265	    }
266	    if (seen.has(name)) {
267	      problems.push(`\`${field}\`: '${name}' is declared more than once.`);
268	      continue;
269	    }
270	    seen.add(name);
271	    names.push(name);
